27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Column(name = "membership_number")
67	    private String membershipNumber;
68	
69	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
70	    private Set<Pet> pets;
71	
72	    /**
73	     * Default the registration date to the server's current date when none was
74	     * supplied, then roll the effective date forward onto a business day so a
75	     * weekend registration date always lands on the following Monday. Runs only
76	     * on insert.
77	     */
78	    @PrePersist
79	    private void defaultRegistrationDate() {
80	        LocalDate effectiveDate = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
81	        this.registrationDate = BusinessDayAdjuster.toBusinessDay(effectiveDate);
82	    }
83	
84	    public String getAddress() {
85	        return this.address;
86	    }
87	
88	    public void setAddress(String address) {
89	        this.address = address;
90	    }
91	
92	    public String getCity() {
93	        return this.city;
94	    }
95	
96	    public void setCity(String city) {
97	        this.city = city;
98	    }
99	
100	    public String getTelephone() {
101	        return this.telephone;
102	    }
103	
104	    public void setTelephone(String telephone) {
105	        this.telephone = telephone;
106	    }
107	
108	    public String getEmail() {
109	        return this.email;
110	    }
111	
112	    public void setEmail(String email) {
113	        this.email = email;
114	    }
115	
116	    public LocalDate getRegistrationDate() {
117	        return this.registrationDate;
118	    }
119	
120	    public void setRegistrationDate(LocalDate registrationDate) {
121	        this.registrationDate = registrationDate;
122	    }
123	
124	    public String getCustomerCode() {
125	        return this.customerCode;
126	    }
127	
128	    public void setCustomerCode(String customerCode) {
129	        this.customerCode = customerCode;
130	    }
131	
132	    public String getHouseholdId() {
133	        return this.householdId;
134	    }
135	
136	    public void setHouseholdId(String householdId) {
137	        this.householdId = householdId;
138	    }
139	
140	    public Integer getNamesakeCount() {
141	        return this.namesakeCount;
142	    }
143	
144	    public void setNamesakeCount(Integer namesakeCount) {
145	        this.namesakeCount = namesakeCount;
146	    }
147	
148	    public String getMembershipNumber() {
149	        return this.membershipNumber;
150	    }
151	
152	    public void setMembershipNumber(String membershipNumber) {
153	        this.membershipNumber = membershipNumber;
154	    }
155	
156	    /**
157	     * Return this owner's name formatted as {@code LastName, FirstName}.
158	     */
159	    @Transient
160	    public String getDisplayName() {
161	        return this.getLastName() + ", " + this.getFirstName();
162	    }
163	
164	    /**
165	     * Return this owner's locality: the canonical region derived from the
166	     * {@link #getCity() city} via the fixed city-to-region table, or
167	     * {@code UNKNOWN} when the city is not in the table.
168	     */
169	    @Transient
170	    public String getLocality() {
171	        return CityRegions.regionOf(this.city);
172	    }
173	
174	    /**
175	     * Return this owner's membership tier: {@code SILVER} for a uniquely-named
176	     * owner (a {@link #getNamesakeCount() namesakeCount} of 0) that has an
177	     * email, otherwise {@code BRONZE}.
178	     */
179	    @Transient
180	    public String getMembershipTier() {
181	        boolean uniquelyNamed = Integer.valueOf(0).equals(this.namesakeCount);
182	        boolean hasEmail = this.email != null && !this.email.isEmpty();
183	        return uniquelyNamed && hasEmail ? "SILVER" : "BRONZE";
184	    }
185	
186	    protected Set<Pet> getPetsInternal() {
187	        if (this.pets == null) {
188	            this.pets = new HashSet<>();
189	        }
190	        return this.pets;
191	    }
192	
193	    protected void setPetsInternal(Set<Pet> pets) {
194	        this.pets = pets;
195	    }
196	
197	    public List<Pet> getPets() {
198	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
199	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
200	        return Collections.unmodifiableList(sortedPets);
201	    }
202	
203	    public void setPets(List<Pet> pets) {
204	        this.pets = new HashSet<>(pets);
205	    }
206	
207	    public void addPet(Pet pet) {
208	        getPetsInternal().add(pet);
209	        pet.setOwner(this);
210	    }
211	
212	    /**
213	     * Return the Pet with the given name, or null if none found for this Owner.
214	     *
215	     * @param name to test
216	     * @return true if pet name is already in use
217	     */
218	    public Pet getPet(String name) {
219	        return getPet(name, false);
220	    }
221	
222	    /**
223	     * Return the Pet with the given name, or null if none found for this Owner.
224	     *
225	     * @param name to test
226	     * @return true if pet name is already in use
227	     */
228	    public Pet getPet(String name, boolean ignoreNew) {
229	        name = name.toLowerCase();
230	        for (Pet pet : getPetsInternal()) {
231	            if (!ignoreNew || !pet.isNew()) {
232	                String compName = pet.getName();
233	                compName = compName.toLowerCase();
234	                if (compName.equals(name)) {
235	                    return pet;
236	                }
237	            }
238	        }
239	        return null;
240	    }
241	
242	    public Pet getPet(Integer petId) {
243	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
244	    }
245	
246	    @Override
247	    public String toString() {
248	        return new ToStringCreator(this)
249	
250	            .append("id", this.getId())
251	            .append("new", this.isNew())
252	            .append("lastName", this.getLastName())
253	            .append("firstName", this.getFirstName())
254	            .append("address", this.address)
255	            .append("city", this.city)
256	            .append("telephone", this.telephone)
257	            .append("email", this.email)
258	            .toString();
259	    }
260	}
