42	import org.springframework.samples.petclinic.rest.validation.CityOwnerCapacityValidator;
43	import org.springframework.samples.petclinic.rest.validation.CityOwnerCounter;
44	import org.springframework.samples.petclinic.rest.validation.CustomerCodeGenerator;
45	import org.springframework.samples.petclinic.rest.validation.DailyRegistrationCapacityValidator;
46	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
47	import org.springframework.samples.petclinic.rest.validation.MembershipNumberGenerator;
48	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
49	import org.springframework.samples.petclinic.rest.validation.NamesakeCounter;
50	import org.springframework.samples.petclinic.rest.validation.OwnerHouseholdRegistrar;
51	import org.springframework.samples.petclinic.rest.validation.OwnerHouseholdUniquenessValidator;
52	import org.springframework.samples.petclinic.rest.validation.OwnerTelephoneUniquenessValidator;
53	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
54	import org.springframework.samples.petclinic.service.ClinicService;
55	import org.springframework.security.access.prepost.PreAuthorize;
56	import org.springframework.web.bind.annotation.CrossOrigin;
57	import org.springframework.web.bind.annotation.RequestMapping;
58	import org.springframework.web.bind.annotation.RestController;
59	import org.springframework.web.util.UriComponentsBuilder;
60	
61	import jakarta.transaction.Transactional;
62	
63	/**
64	 * @author Vitaliy Fedoriv
65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    private final OwnerTelephoneUniquenessValidator telephoneUniquenessValidator;
81	
82	    private final OwnerHouseholdUniquenessValidator householdUniquenessValidator;
83	
84	    private final OwnerHouseholdRegistrar householdRegistrar;
85	
86	    private final NamesakeCounter namesakeCounter;
87	
88	    private final CityOwnerCounter cityOwnerCounter;
89	
90	    private final CityOwnerCapacityValidator cityOwnerCapacityValidator;
91	
92	    private final DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator;
93	
94	    private final OwnerAuditLogger ownerAuditLogger;
95	
96	    public OwnerRestControllerV1(ClinicService clinicService,
97	                                 OwnerMapper ownerMapper,
98	                                 PetMapper petMapper,
99	                                 VisitMapper visitMapper,
100	                                 OwnerTelephoneUniquenessValidator telephoneUniquenessValidator,
101	                                 OwnerHouseholdUniquenessValidator householdUniquenessValidator,
102	                                 OwnerHouseholdRegistrar householdRegistrar,
103	                                 NamesakeCounter namesakeCounter,
104	                                 CityOwnerCounter cityOwnerCounter,
105	                                 CityOwnerCapacityValidator cityOwnerCapacityValidator,
106	                                 DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator,
107	                                 OwnerAuditLogger ownerAuditLogger) {
108	        this.clinicService = clinicService;
109	        this.ownerMapper = ownerMapper;
110	        this.petMapper = petMapper;
111	        this.visitMapper = visitMapper;
112	        this.telephoneUniquenessValidator = telephoneUniquenessValidator;
113	        this.householdUniquenessValidator = householdUniquenessValidator;
114	        this.householdRegistrar = householdRegistrar;
115	        this.namesakeCounter = namesakeCounter;
116	        this.cityOwnerCounter = cityOwnerCounter;
117	        this.cityOwnerCapacityValidator = cityOwnerCapacityValidator;
118	        this.dailyRegistrationCapacityValidator = dailyRegistrationCapacityValidator;
119	        this.ownerAuditLogger = ownerAuditLogger;
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
125	        Collection<Owner> owners;
126	        if (lastName != null) {
127	            owners = this.clinicService.findOwnerByLastName(lastName);
128	        } else {
129	            owners = this.clinicService.findAllOwners();
130	        }
131	        if (owners.isEmpty()) {
132	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
133	        }
134	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
140	        Owner owner = this.clinicService.findOwnerById(ownerId);
141	        if (owner == null) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Override
149	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
150	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
151	        OwnerFieldsValidator.validateRequiredFields(ownerFieldsDto);
152	        HttpHeaders headers = new HttpHeaders();
153	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
154	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
155	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
156	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
157	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
158	        this.dailyRegistrationCapacityValidator.validateHasCapacity(owner.getRegistrationDate());
159	        this.telephoneUniquenessValidator.validateUnique(owner.getTelephone());
160	        this.cityOwnerCapacityValidator.validateHasCapacity(owner.getCity());
161	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
162	            this.householdUniquenessValidator.validateUnique(owner.getLastName(), owner.getAddress());
163	        } else {
164	            this.householdRegistrar.assignHousehold(owner);
165	        }
166	        owner.setNamesakeCount(this.namesakeCounter.count(owner.getFirstName(), owner.getLastName()));
167	        owner.setCustomerCode(CustomerCodeGenerator.generate(owner.getCity(), owner.getLastName(),
168	            this.cityOwnerCounter.count(owner.getCity())));
169	        this.clinicService.saveOwner(owner);
170	        owner.setMembershipNumber(MembershipNumberGenerator.generate(owner.getCustomerCode(), owner.getRegistrationDate()));
171	        this.ownerAuditLogger.logCreated(owner);
172	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
173	        headers.setLocation(UriComponentsBuilder.newInstance()
174	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
175	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
181	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
182	        if (currentOwner == null) {
183	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	        }
185	        currentOwner.setAddress(ownerFieldsDto.getAddress());
186	        currentOwner.setCity(ownerFieldsDto.getCity());
187	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
188	        currentOwner.setLastName(ownerFieldsDto.getLastName());
189	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
190	        this.clinicService.saveOwner(currentOwner);
191	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
192	    }
193	
194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Transactional
196	    @Override
197	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
198	        Owner owner = this.clinicService.findOwnerById(ownerId);
199	        if (owner == null) {
200	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
201	        }
202	        this.clinicService.deleteOwner(owner);
203	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
204	    }
205	
206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Override
208	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
209	        Owner owner = this.clinicService.findOwnerById(ownerId);
210	        if (owner == null) {
211	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
212	        }
213	        HttpHeaders headers = new HttpHeaders();
214	        Pet pet = petMapper.toPet(petFieldsDto);
215	        owner.setId(ownerId);
216	        pet.setOwner(owner);
217	        pet.getType().setName(null);
218	        this.clinicService.savePet(pet);
219	        PetDto petDto = petMapper.toPetDto(pet);
220	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
221	            .buildAndExpand(pet.getId()).toUri());
222	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
223	    }
224	
225	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
226	    @Override
227	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
228	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
229	        if (currentOwner != null) {
230	            Pet currentPet = this.clinicService.findPetById(petId);
231	            if (currentPet != null) {
232	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
233	                currentPet.setName(petFieldsDto.getName());
234	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
235	                this.clinicService.savePet(currentPet);
236	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
237	            }
238	        }
239	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
240	    }
